#!/usr/bin/env node

// SPDX-License-Identifier: MIT

/**
 * Generate `public/llms-full.txt` from the app catalog. The file is
 * the LLM-friendly mirror of every app detail page on the site —
 * one section per app with name, repo, category, stack, platforms,
 * description, stars, and last-commit relative time.
 *
 * Regenerated on every build (wired into `prebuild` in package.json)
 * because the data comes from `data/generated/apps.json` which is
 * itself regenerated by `build:data` from `data/apps/*.yml`.
 *
 * The output is git-tracked so it survives in the published `dist/`
 * even if the build is run from a fresh checkout with no `apps.json`
 * available — see `sync:llms-full` for a one-shot regen in that case.
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const SOURCE = join(ROOT, "data", "generated", "apps.json");
const OUT_DIR = join(ROOT, "public");
const TARGET = join(OUT_DIR, "llms-full.txt");

const SITE = process.env.OPEN_APPS_SITE ?? "https://open-apps.dev.mn";

function compactStars(n) {
  if (typeof n !== "number" || !Number.isFinite(n)) return "—";
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1).replace(/\.0$/, "") + "M";
  if (n >= 1_000) {
    const k = n / 1_000;
    return (k >= 10 ? Math.round(k).toString() : k.toFixed(1).replace(/\.0$/, "")) + "k";
  }
  return n.toString();
}

function relativeTime(iso, now = new Date()) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "—";
  const diffMs = now.getTime() - d.getTime();
  const sec = Math.max(1, Math.round(diffMs / 1000));
  if (sec < 60) return `${sec}s ago`;
  const min = Math.round(sec / 60);
  if (min < 60) return `${min}m ago`;
  const hr = Math.round(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const day = Math.round(hr / 24);
  if (day < 30) return `${day}d ago`;
  const mon = Math.round(day / 30);
  if (mon < 12) return `${mon}mo ago`;
  const yr = Math.round(day / 365);
  return `${yr}y ago`;
}

function escape(s) {
  if (typeof s !== "string") return "";
  return s.replace(/\r?\n+/g, " ").trim();
}

function render(apps) {
  const out = [];
  out.push("# Open Source Apps — full directory");
  out.push("");
  out.push(`> Generated ${new Date().toISOString()} from ${apps.length} app records.`);
  out.push(`> Source: ${SITE}/apps · Regenerate with \`pnpm run build:llms-full\`.`);
  out.push("");
  out.push("Each section below mirrors one app detail page. Use these for");
  out.push("grounded citations about a specific app — for the site-wide LLM");
  out.push("overview see [/llms.txt](/llms.txt).");
  out.push("");
  out.push("## Index");
  out.push("");
  for (const a of apps) {
    out.push(`- [${a.name}](#${a.slug}) — ${a.category} · ${a.stack ?? "—"} · ${compactStars(a.stars)} stars`);
  }
  out.push("");
  out.push("## Apps");
  out.push("");
  for (const a of apps) {
    out.push(`### ${escape(a.name)}`);
    out.push(`Slug: ${a.slug}`);
    out.push(`URL: ${SITE}/apps/${a.slug}`);
    out.push(`Repository: ${escape(a.repoUrl)}`);
    out.push(`Category: ${escape(a.category ?? "—")}`);
    out.push(`Stack: ${escape(a.stack ?? "—")}`);
    out.push(`Platforms: ${Array.isArray(a.platforms) && a.platforms.length > 0 ? a.platforms.join(", ") : "—"}`);
    out.push(`Description: ${escape(a.description ?? "—")}`);
    out.push(`Stars: ${compactStars(a.stars)}`);
    out.push(`Forks: ${compactStars(a.activity?.forks)}`);
    out.push(`Last commit: ${escape(a.lastCommitAt ?? a.activity?.lastCommitAt ?? "—")} (${relativeTime(a.lastCommitAt ?? a.activity?.lastCommitAt)})`);
    out.push(`Status: ${escape(a.health?.status ?? a.activity?.status ?? "—")}`);
    out.push(`Tier: ${escape(a.tier ?? "—")}`);
    out.push("");
  }
  out.push("---");
  out.push("");
  out.push(`Last regenerated: ${new Date().toUTCString()}`);
  out.push("");
  return out.join("\n");
}

async function main() {
  const raw = await readFile(SOURCE, "utf8");
  const data = JSON.parse(raw);
  const apps = Array.isArray(data.apps) ? data.apps : [];
  if (apps.length === 0) {
    throw new Error(
      `No apps found in ${SOURCE}. Run \`pnpm run build:data\` first to regenerate apps.json.`,
    );
  }
  // Sort by stars desc so the most prominent apps come first.
  apps.sort((a, b) => (b.stars ?? 0) - (a.stars ?? 0));

  const next = render(apps);
  const current = await readFile(TARGET, "utf8").catch(() => "");
  if (current === next) {
    console.log(`[build-llms-full] no changes (${apps.length} apps).`);
    return;
  }
  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(TARGET, next, "utf8");
  console.log(`[build-llms-full] wrote ${apps.length} apps to ${TARGET}.`);
}

main().catch((err) => {
  console.error("[build-llms-full] failed:", err.message);
  process.exit(1);
});
